from deepagents import create_deep_agent


def verify_solution(solution: str) -> str:
    """Check a proposed solution and report issues."""
    if not solution.strip():
        return "The solution is empty."
    return "The solution is ready for review."

agent = create_deep_agent(
    tools=[verify_solution],
    system_prompt="Use verify_solution before accepting a final solution.",
)

result = agent.invoke({"messages": [{
    "role": "user",
    "content": "Review this solution: return 42"
}]})
print(result)
